A = [
dict(n=53, slug="rag", title="How Does an AI Answer From Your Documents?", topic="RAG",
buzz='"Just add RAG." It\'s the most common way companies make AI answer from their own documents. The acronym hides a simple idea.',
hw='An open-book exam. The student doesn\'t need to remember the whole textbook. They find the right page, read it, then write the answer.\n\nThat\'s the hello world: **RAG** means the AI first **retrieves** the relevant pages from your documents, then **generates** its answer from them.',
step='Your documents are split into chunks and stored for search, often using embeddings (write-up 12) in a vector database (write-up 54). When a question comes in, the system finds the most relevant chunks and puts them on the AI\'s desk (write-up 15) with the question. The AI answers from what it was given, ideally with citations (write-up 59).\n\nThe answer can only be as good as what was found. If retrieval picks the wrong page, the AI answers confidently from the wrong page.',
met='"Ask your documents" features, company help chatbots, AI search that shows sources.',
name='**RAG**, retrieval-augmented generation.',
words=[("Retrieval","finding the relevant pieces of information."),("Chunk","a small piece of a document stored for search."),("Generation","the AI writing the answer.")],
notit='RAG isn\'t retraining the AI on your documents, and it isn\'t "plug in and done". Why it takes months to get right is the whole of my #JustAddRAG series.',
take=["Picture an open-book exam: finding the right page is half the job.","Check which sources an answer used.","Read #JustAddRAG before promising \"just add RAG\" in two weeks."],
close="Find the right page. Then answer.",
q="Has an AI ever answered from the wrong page for you?",
scene='An open-book exam.\nFind the right page, then write the answer.',
hook="RAG is an AI doing an open-book exam on your documents.",
extra="Find first, then answer."),

dict(n=54, slug="vector-database", title="Where Does an AI Store Meaning?", topic="Vector database",
buzz='"We need a vector database." Startups raised millions on it. It sounds like a maths warehouse.',
hw='A normal database is a filing cabinet sorted by name: find "Invoice 4471" instantly. But ask it for "documents about late payments" and it only finds exact words.\n\nA vector database is a map of meaning (write-up 12). That\'s the hello world: it stores each piece of text as a point on that map, so you can find the points **closest in meaning** to your question.',
step='Every chunk of text is turned into an embedding, a long list of numbers, and stored. A question is turned into an embedding too. The database quickly finds the nearest points among millions, using clever shortcuts so it doesn\'t compare every single one.\n\nIt powers semantic search (write-up 55) and RAG (write-up 53). Many ordinary databases now add vector search too.',
met='Behind AI search in apps, "similar products" suggestions, and document chatbots.',
name='A **vector database**.',
words=[("Vector","a list of numbers representing meaning."),("Nearest neighbour","the closest stored point to your question."),("Index","the structure that makes searching fast.")],
notit='A vector database doesn\'t understand or check facts. It finds similar-sounding text, which can be similar but wrong. And you may not need a separate one; your existing database might do vectors.',
take=["Check if your current database already supports vector search.","Combine meaning search with keyword search for names and codes.","Test retrieval quality before blaming the AI."],
close="A filing cabinet sorted by meaning.",
q="Does your team really need a separate vector database?",
scene='A filing cabinet sorted by name finds "Invoice 4471".\nIt can\'t find "documents about late payments".',
hook="A vector database is a filing cabinet sorted by meaning.",
extra="It finds what's closest in meaning, not in spelling."),

dict(n=55, slug="semantic-search", title="How Does Search Understand What You Meant?", topic="Semantic search",
buzz='"Semantic search." It\'s why search boxes got smarter. The word sounds academic.',
hw='Search a recipe site for "quick dinner without meat". Old search looks for those exact words and misses "20-minute vegetarian pasta".\n\nThat\'s the hello world: **semantic search** finds results by **meaning**, not just matching words.',
step='Both your query and the documents are turned into embeddings (write-up 12), points on a meaning map. Results are the documents closest to your query, even if they share no words.\n\nIt\'s great for natural questions, but weaker for exact things like product codes or names. That\'s why good systems mix it with keyword search, called hybrid search.',
met='Search boxes that find "budget airfares" when you typed "cheap flights". Photo apps that find "beach" without tags.',
name='**Semantic search**, often combined into **hybrid search**.',
words=[("Semantic","about meaning."),("Keyword search","matching the exact words."),("Hybrid search","combining meaning and keyword search.")],
notit='Semantic search isn\'t always better. For exact names, IDs and codes, plain keyword search often wins.',
take=["Use semantic search for natural-language questions.","Keep keyword search for names, IDs and codes.","Test with real questions your users ask."],
close="Search by meaning, not just by spelling.",
q="When did a search box last understand what you meant?",
scene='"Quick dinner without meat."\nOld search misses "20-minute vegetarian pasta".',
hook="Semantic search finds results by meaning, not just matching words.",
extra="Mix it with keyword search for names and codes."),

dict(n=56, slug="knowledge-graph", title="How Do You Teach an AI Who Is Connected to Whom?", topic="Knowledge graph",
buzz='"Knowledge graph." Google, LinkedIn and many AI products use one. It sounds like a complicated chart.',
hw='Draw dots for people and companies. Draw a line from "Priya" to "Acme Ltd" labelled "works at", and from "Acme Ltd" to "Mumbai" labelled "based in".\n\nThat\'s the hello world: a **knowledge graph** stores facts as things and the labelled links between them.',
step='Instead of storing paragraphs, it stores relationships: who reports to whom, which product uses which part, which drug interacts with which. That makes questions like "Which suppliers of Acme are based in Mumbai?" easy to answer exactly, by following the links.\n\nBuilding one takes work: someone (or an AI) has to extract the facts and keep them up to date. GraphRAG (write-up 57) combines knowledge graphs with AI answers.',
met='Google\'s information panel on the right of search results. "People you may know" on social networks.',
name='A **knowledge graph**.',
words=[("Node","a thing: a person, company or place."),("Edge","a labelled link between two things."),("Triple","one fact: thing, link, thing.")],
notit='A knowledge graph isn\'t a chart you draw once. It\'s a living database that needs updating. And it\'s not needed for every AI project.',
take=["Use a graph when questions are about connections between things.","Plan who keeps the facts up to date.","Start small: one domain, a few relationship types."],
close="Dots and labelled lines. Facts you can follow.",
q="Where would \"who is connected to whom\" questions help your team?",
scene='Priya works at Acme. Acme is based in Mumbai.\nDots and labelled lines.',
hook="A knowledge graph stores facts as things and the links between them.",
extra="Questions about connections become easy to follow."),

dict(n=57, slug="graphrag", title="How Does an AI Answer Questions About a Whole Pile of Documents?", topic="GraphRAG",
buzz='"GraphRAG." A newer twist on RAG that\'s trending in enterprise AI. Why add a graph?',
hw='Ask: "What are the common causes across all 500 incident reports from last year?" Normal RAG (write-up 53) finds a few similar pages, but no single page holds the answer.\n\nThat\'s the hello world: **GraphRAG** first builds a map of the people, systems and events across all documents (a knowledge graph, write-up 56), then answers from that map.',
step='An AI reads every document and extracts the important things and how they connect. Related groups are summarised. When a big-picture question arrives, the system answers from those summaries and links, not just from a few matching chunks.\n\nIt\'s good for "across everything" and "how is X connected to Y" questions. It costs more to build and to keep updated than plain RAG.',
met='Enterprise research and investigation tools that summarise themes across thousands of documents.',
name='**GraphRAG** (graph-based retrieval-augmented generation).',
words=[("Entity","a person, system, place or event pulled from text."),("Community summary","a summary of a group of connected entities."),("Multi-hop question","one that needs several linked facts.")],
notit='GraphRAG isn\'t automatically better than RAG. For simple "find the answer on a page" questions, plain RAG is cheaper and enough. (Knowledge graphs in production are covered in Series 13.)',
take=["Use GraphRAG for big-picture and connection questions.","Use plain RAG for single-fact look-ups.","Budget for building and refreshing the graph."],
close="Map everything first. Then answer the big question.",
q="Do your hardest questions span many documents?",
scene='"What are the common causes across 500 incident reports?"\nNo single page holds the answer.',
hook="GraphRAG maps everything first, then answers from the map.",
extra="For big-picture questions plain RAG can't handle."),

dict(n=58, slug="grounding", title="How Do You Keep an AI Tied to the Facts?", topic="Grounding",
buzz='"Grounded answers." AI vendors promise them. It sounds like electrical safety.',
hw='Two students answer "When was the company founded?" One answers from memory, confidently. The other opens the annual report, finds the line, and answers from it.\n\nThat\'s the hello world: **grounding** means tying an AI\'s answer to a specific, trusted source instead of its memory.',
step='The source is put on the AI\'s desk (write-up 15), from documents (write-up 53), a database, or a web search. The AI is instructed to answer only from it and to say so when the source doesn\'t contain the answer.\n\nGrounding reduces hallucinations (write-up 83) a lot, but doesn\'t remove them: the AI can still misread or overstate the source. Citations (write-up 59) let people check.',
met='AI answers that say "according to your document" or show search results they used.',
name='**Grounding**.',
words=[("Grounding","basing answers on a provided source."),("Source","the trusted text the answer comes from."),("Faithfulness","how closely the answer sticks to the source.")],
notit='Grounded isn\'t the same as correct. If the source is out of date or wrong, a grounded answer is too.',
take=["Give the AI the source instead of trusting its memory.","Tell it to say \"not in the source\" when it doesn't know.","Keep sources up to date; grounding repeats their mistakes."],
close="Answer from the report, not from memory.",
q="Do your AI answers say where they came from?",
scene='One student answers from memory.\nThe other opens the annual report first.',
hook="Grounding makes the AI the second student.",
extra="Tied to a source. Only as good as the source."),

dict(n=59, slug="citations", title="How Do You Check Where an AI Got Its Answer?", topic="Citations",
buzz='"With citations." It\'s a trust feature AI products advertise. But are the citations always real?',
hw='A good research report puts a small number after each claim: [1], [2]. At the bottom, [1] tells you exactly which source said it.\n\nThat\'s the hello world: **citations** link each part of an AI\'s answer to the source it came from, so you can check.',
step='When an AI answers from given documents (write-ups 53 and 58), the system can label each source and ask the AI to mark which one supports each claim. Some systems quote the exact sentence.\n\nWithout given sources, an AI asked to "add references" may invent plausible ones (write-up 83). Real citations come from real retrieved sources, not from memory.',
met='AI search tools with numbered source links. Document chatbots that highlight the passage they used.',
name='**Citations**, also called **attribution**.',
words=[("Citation","a pointer to the source behind a claim."),("Attribution","linking an answer to where it came from."),("Quote","the exact source text, shown alongside.")],
notit='A citation isn\'t proof the claim is right. Click it: the source may not actually say that.',
take=["Click at least one citation before trusting an important answer.","Never ask an AI to add references from memory.","Prefer tools that quote the exact source sentence."],
close="Every claim, with its receipt.",
q="Do you click the citations, or just trust them?",
scene='A good report puts [1] after each claim.\nAt the bottom: exactly which source said it.',
hook="Citations give every AI answer a receipt.",
extra="Click one before you trust it."),

dict(n=60, slug="deep-research", title="Can an AI Do Your Research for You?", topic="Deep research",
buzz='"Deep research." Several AI apps launched it: ask a question, wait 10 minutes, get a report. What\'s it doing in those minutes?',
hw='A junior analyst gets a question: "How big is the Indian EV charging market?" They search, read 30 pages, notice gaps, search again, take notes, and write a 5-page report with sources.\n\nThat\'s the hello world: **deep research** is an AI agent (write-up 61) doing that whole loop on its own.',
step='Instead of one quick answer, the AI plans sub-questions, runs many web searches, reads the results, decides what\'s missing, searches again, and finally writes a structured report with citations (write-up 59). It can take minutes and hundreds of pages read.\n\nIt\'s great for a first draft of a research brief. It can still pick weak sources, miss paywalled data or misread numbers.',
met='"Deep research" or "research" modes in major AI chat apps.',
name='**Deep research** agents.',
words=[("Research agent","an AI that plans, searches and reads in a loop."),("Sub-question","a smaller question the main one is split into."),("Report","the final written summary with sources.")],
notit='Deep research isn\'t expert review. Treat the report like a junior analyst\'s first draft: useful, but check the key numbers and sources.',
take=["Use it to get a sourced first draft fast.","Check the most important numbers against original sources.","Ask it to list what it couldn't find."],
close="A tireless junior analyst. Still check the numbers.",
q="Would you trust an AI-written research report?",
scene='A junior analyst searches, reads 30 pages, searches again,\nand writes a 5-page report.',
hook="Deep research is an AI doing that whole loop on its own.",
extra="A sourced first draft. Still check the numbers."),
]
